-- Public presentation metadata only. Pack awards and inventories remain server-owned.
create table if not exists public.published_card_designs (
  id text primary key check (id ~ '^[a-z0-9][a-z0-9_-]{0,119}$'),
  collection_key text not null default 'los-nuestros-01' check (collection_key ~ '^[a-z0-9_-]{1,80}$'),
  collection_name text not null default 'Los nuestros · Colección 01' check (length(collection_name) between 1 and 100),
  display_name text not null check (length(btrim(display_name)) between 1 and 120),
  display_kind text not null check (display_kind in ('Miembro','Personaje','Objeto','Ubicación')),
  rarity text not null check (rarity in ('common','retro','special','epic','legendary','full_art','vice_city','halloween')),
  score integer check (score between 0 and 100),
  front_url text not null, back_url text not null, thumbnail_url text not null,
  width integer not null default 948 check (width between 100 and 4096),
  height integer not null default 1660 check (height between 100 and 4096),
  published boolean not null default false,
  updated_at timestamptz not null default now(),
  constraint approved_card_media check (
    front_url ~ '^https://(nfvggpgeypkkqceivkaq\.supabase\.co/storage/v1/object/public/card-artwork/|raulculsan\.github\.io/The-Big-Boy-Rules/icons/cards/)[a-zA-Z0-9/_?.=&%-]+$'
    and back_url ~ '^https://(nfvggpgeypkkqceivkaq\.supabase\.co/storage/v1/object/public/card-artwork/|raulculsan\.github\.io/The-Big-Boy-Rules/icons/cards/)[a-zA-Z0-9/_?.=&%-]+$'
    and thumbnail_url ~ '^https://(nfvggpgeypkkqceivkaq\.supabase\.co/storage/v1/object/public/card-artwork/|raulculsan\.github\.io/The-Big-Boy-Rules/icons/cards/)[a-zA-Z0-9/_?.=&%-]+$'
  )
);
alter table public.published_card_designs enable row level security;
revoke all on public.published_card_designs from anon, authenticated;
grant select on public.published_card_designs to anon, authenticated;
grant insert, update, delete on public.published_card_designs to authenticated;
drop policy if exists "Published card designs are public" on public.published_card_designs;
create policy "Published card designs are public" on public.published_card_designs for select to anon, authenticated using (published);
drop policy if exists "Superadmin manages card designs" on public.published_card_designs;
create policy "Superadmin manages card designs" on public.published_card_designs for all to authenticated
  using ((select public.current_user_is_superadmin()) and (select public.account_security_satisfied()))
  with check ((select public.current_user_is_superadmin()) and (select public.account_security_satisfied()));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values ('card-artwork','card-artwork',true,8388608,array['image/png','image/jpeg','image/webp'])
on conflict(id) do update set public=true,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "Superadmin reads card artwork objects" on storage.objects;
create policy "Superadmin reads card artwork objects" on storage.objects for select to authenticated
  using (bucket_id='card-artwork' and (select public.current_user_is_superadmin()));
drop policy if exists "Superadmin uploads card artwork" on storage.objects;
create policy "Superadmin uploads card artwork" on storage.objects for insert to authenticated
  with check (bucket_id='card-artwork' and (select public.current_user_is_superadmin()));
drop policy if exists "Superadmin updates card artwork" on storage.objects;
create policy "Superadmin updates card artwork" on storage.objects for update to authenticated
  using (bucket_id='card-artwork' and (select public.current_user_is_superadmin()))
  with check (bucket_id='card-artwork' and (select public.current_user_is_superadmin()));
drop policy if exists "Superadmin deletes card artwork" on storage.objects;
create policy "Superadmin deletes card artwork" on storage.objects for delete to authenticated
  using (bucket_id='card-artwork' and (select public.current_user_is_superadmin()));

